var redis = require('redis')
  , winston = require('winston');

var RedisStorage = module.exports = function(port, host, options, verbosity) {
  var _this = this;

  // default values
  port = port || 6379;
  host = host || 'localhost';
  options = options || {};
  verbosity = verbosity || 'info';

  // configure the log
  this.log = new (winston.Logger)({
    transports: [
      new (winston.transports.Console)({
        colorize: true,
        timestamp: true,
        level: verbosity
      })
    ]
  });

  this.up = false; // used to track status of connection

  // connect to redis server
  this.client = redis.createClient(port, host);
  this.client.on('end', function() {
    _this.log.warn("Disconnected from Host: " + host + ", Port: " + port);
    _this.up = false;
  });
  this.client.on('error', function(err) {
    _this.log.error(err.toString());
    _this.up = false;
  });
  this.client.on('ready', function() {
    _this.log.info("Connected to Host: " + host + ", Port: " + port);
    _this.up = true;
  });
  if (options.auth) {
    this.client.auth(options.auth);
  }
  this.log.info("Redis storage initializing");
};

// retrieve a specific resource or multiple if multiple keys are defined
RedisStorage.prototype.get = function(key, callback) {
  var _this = this;
  if (this.up) {
    if(Object.prototype.toString.call(key) === '[object Array]') {
      this.client.mget(key, function(err, results) {
        if (err) {
          _this.log.error(err);
        }

        var list = [];
        for(var i=0; i<results.length; i++) {
          var r = JSON.parse(results[i]);
          r = r || {};
          r.key = key[i];
          list.push(r);
        }

        callback(err, err ? null : list);
      });
    } else {
      this.client.get(key, function(err, results) {
        if (err) {
          _this.log.error(err);
        }

        var r = JSON.parse(results);
        r = r || {};
        r.key = key;
        callback(err, err ? null : r);
      });
    }
  } else {
    callback("Redis unavailable");
  }
};

// save a specific resource
RedisStorage.prototype.put = function(resource, callback) {
  var _this = this;
  if (this.up) {
    _this.client.setex(resource.key, resource.options.maxLife, JSON.stringify(resource), function(err, results) {
      if (err != null) {
        _this.log.error(err);
      }

      if (callback) {
        callback(err, results);
      }
    });
  } else {
    callback("Redis unavailable");
  }
  return this;
};

