var url = require('url')
  , querystring = require('querystring')
  , request = require('request')
  , EventEmitter = require('events').EventEmitter
  , MemoryStorage = require('./redpantry-memory')
  , RedisStorage = require('./redpantry-redis')
  , winston = require('winston')
  , inProgress = [];


function getLogLevel() {
  switch (process.env.NODE_ENV) {
    case 'production':
      return 'info';
    case 'test':
      return 'error';
    default:
      return 'silly';
  }
}

config = {
  shelfLife: 60,
  maxLife: 300,
  caseSensitive: true,
  ignoreCacheControl: false,
  cacheBuster: null,
  verbosity: process.env.PANTRY_VERBOSITY || getLogLevel(),
  xmlOptions: {
    explicitRoot: false
  },
  redis: null,
  shopper: null,
  shopperAuth: null
};

var log = new (winston.Logger)({
  transports: [
    new (winston.transports.Console)({
      colorize: true,
      timestamp: true,
      level: config.verbosity
    })
  ]
});

var RedPantry = module.exports = {
  storage: null,
  backup: new MemoryStorage(config, config.verbosity)
};

RedPantry.configure = function(options) {
  for (var k in options) {
    config[k] = options[k];
  }

  if(config['redis'] != null) {
    var rtg = require("url").parse(config['redis']);

    RedPantry.storage = new RedisStorage(rtg.port, rtg.hostname, { auth: rtg.auth.split(':')[1] }, config.verbosity);
  }

  return config;
};

RedPantry.fetch = function(options, callback) { 
