    options = {
      uri: options
    };
  }

  for (var k in config) {
    if (options[k] == null)
      options[k] = config[k];
  }

  if (options.method != null && options.method !== 'GET') {
    options.maxLife = 0;
  }

  // These two lines solve the problem that a user may have submitted the values as strings, which affects cache lifetime
  options.maxLife = parseInt(options.maxLife);
  options.shelfLife = parseInt(options.shelfLife);

  var key = null;
  if (options.key != null)
    key = options.key;
  else
    key = RedPantry.generateKey(options);

  RedPantry.fromCache(key, function(error, resource) {
    if(Object.prototype.toString.call(resource) === '[object Array]') {
      var pending = resource.length;
      var list = [];
      var isError = null;

      for(var i=0; i<resource.length; i++) {
        if(isError) {
          callback(isError, list);
          break;
        }

        RedPantry.validate(error, resource[i], options, function(err, res, type, index) {
          if(err) {
            isError = err;
          }
          else {
            list[index] = res[0];
          }

          pending--;

          if(pending == 0) {
            callback(isError, list);
          }
