          var shopperOptions = {
            uri: config.shopper,
            qs: {
              key: resource.key,
              required: resourceRequired,
              cacheBuster: options.cacheBuster || null
            },
            timeout: parseInt(options.timeout) || 10000,
            maxSockets: parseInt(options.maxSockets) || 10,
            headers: {
              'shopper': config.shopperAuth
            }
          };

          if(!resourceRequired) {
            log.info("shopper notify: " + resource.key);

            request(shopperOptions, function(error, response, body) {
              if (error) {
                log.warn("shopper down: " + shopperOptions.uri + ", " + error);
              } else if (response.statusCode != 200) {
                log.warn("shopper error: " + shopperOptions.uri + ", " + response.statusCode);
