              var e = false;

              if (error) {
                log.warn("shopper down: " + shopperOptions.uri + ", " + error);
                e = true;
              } else {
                switch (response.statusCode) {
                  case 200:
                    log.info("shopper gave: " + resource.key);
                    resource.contentType = response.headers["content-type"];

                    if (response.headers['etag'] != null)
                      resource.etag = response.headers['etag'];

                    if (response.headers['last-modified'] != null)
                      resource.lastModified = response.headers['last-modified'];

                    try {
                      resource.results = JSON.parse(body);
                      RedPantry.done(null, stock);
                    } catch (err) {
                      RedPantry.done(err, stock);
                    }
