                log.info("shopper bypass: " + resource.key);
                RedPantry.request(options, stock);
              }
            }); 
          }
        } else {
          RedPantry.request(options, stock);
        }
      } catch (err) {
        return RedPantry.done(err, stock);
      }
    }
  }
};

RedPantry.request = function(options, stock, isRetry) {
  var resource = stock.resource;

  var uri = url.parse(resource.key, true);

  // apply cache buster if configured
  if (options.cacheBuster) {
    var ts = new Date();
    uri.query[options.cacheBuster] = ts.getTime();
    delete uri.search;
  }

  // always set request uri
  options.uri = url.format(uri);

  request(options, function(error, response, body) {
    if (error) {
      var returnStatus;

      try {
          returnStatus = RedPantry.done(error, stock);
      } catch (err) {
          log.error("" + err);
          log.error("Request URL: " + options.uri);
          returnStatus = RedPantry.done("Error (" + response.statusCode + ")", stock);
      }

      return returnStatus;
    } else {
      switch (response.statusCode) {
        case 304:
          log.info("cache edible: " + resource.key);
          RedPantry.done(null, stock);
          break;

        case 200:
          log.info("receiving: " + resource.key);
          resource.contentType = response.headers["content-type"];

          if (response.headers['etag'] != null)
            resource.etag = response.headers['etag'];

          if (response.headers['last-modified'] != null)
            resource.lastModified = response.headers['last-modified'];

          try {
            resource.results = JSON.parse(body);

            if(resource.results === null)
              throw new Error('null body: ' + resource.key);

            RedPantry.done(null, stock);
          } catch (err) {
            // retry once if there was an error
            if(isRetry) {
              RedPantry.done(err, stock);
            } else {
              log.error("" + err);
              log.info("retrying: " + resource.key);
              RedPantry.request(options, stock, true);
            }
          }

          break;

        default:
          return RedPantry.done("Invalid Response Code (" + response.statusCode + ")", stock);
      }
    }
  });
};

RedPantry.fromCache = function(key, callback) {
  if (RedPantry.storage == null)
    RedPantry.storage = RedPantry.backup;

  RedPantry.storage.get(key, function(error, resource) {
    if (error) {
      log.error("primary failure: " + key + ": " + error);

      RedPantry.backup.get(key, function(error, resource) {
        callback(error, resource);
      });
    } else {
      callback(error, resource);
    }
  });
};

RedPantry.done = function(err, stock) {
  delete inProgress[stock.resource.key];

  if (err) {
    log.error("" + err);
    stock.emit('done', err);
  } else {
    var resource = stock.resource;
    resource.lastPurchased = new Date();
    resource.firstPurchased = resource.firstPurchased || resource.lastPurchased;
    resource.bestBefore = new Date(resource.lastPurchased);
    resource.bestBefore.setSeconds(resource.bestBefore.getSeconds() + resource.options.shelfLife);
    resource.spoilsOn = new Date(resource.lastPurchased);
    resource.spoilsOn.setSeconds(resource.spoilsOn.getSeconds() + resource.options.maxLife);

    stock.emit('done', null, resource.results, resource.contentType, resource.index);

    if (resource.options.maxLife > 0) {
      RedPantry.storage.put(resource, function(error) {
        if (error) {
          log.error("caching error: " + resource.key + ": " + error);
          RedPantry.backup.put(resource);
        }
      });
    }
  }
};

RedPantry.generateKey = function(options) {
  var generated = [];
  if(Object.prototype.toString.call(options.uri) !== '[object Array]') {
    options.uri = [options.uri];
  }

  options.uri.forEach(function(u) {
    var uri = url.parse(u, true);
    var keys = [];

    for (var k in uri.query) {
      keys.push(k);
    }
    keys.sort();

    var query = {};
    keys.forEach(function(k) {
      if (uri.query.hasOwnProperty(k))
        query[options.caseSensitive ? k : k.toLowerCase()] = uri.query[k];    
    });

    uri.search = querystring.stringify(query);
    if (!options.caseSensitive) {
      uri.pathname = uri.pathname.toLowerCase();
    }

    generated.push(url.format(uri));
  });

  return generated.length == 1 ? generated[0] : generated;
};

RedPantry.exists = function(resource) {
  return (resource.results != null);
};

RedPantry.hasSpoiled = function(resource) {
  return !(resource.results != null) || typeof resource.spoilsOn === 'undefined' || (new Date() > new Date(resource.spoilsOn));
};

RedPantry.hasExpired = function(resource) {
  return RedPantry.hasSpoiled(resource) || typeof resource.bestBefore === 'undefined' || (new Date() > new Date(resource.bestBefore));
};

